sys_script_include.script:
// Script Include: TrainingUtils
var TrainingUtils = Class.create();
TrainingUtils.prototype = {
    initialize: function() {},

    refQualSchedules: function(userId, scheduleId) {

        var enrolledSchedules = [];
        var grEnrollment = new GlideRecord("x_1593183_traini_0_training_enrollments");
        grEnrollment.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe");
        grEnrollment.query();
        while (grEnrollment.next()) {
            enrolledSchedules.push(grEnrollment.schedule.sys_id.toString()); // Use getValue for sys_id
        }

        gs.info("Enrolled Schedules: " + enrolledSchedules.join(",")); // More informative logging

        var availableSchedules = [];
        var grSchedules = new GlideRecord("x_1593183_traini_0_training_schedules");
        grSchedules.addQuery("status", "1");
        grSchedules.query();
        while (grSchedules.next()) {
            var scheduleSysId = grSchedules.getUniqueValue();
            if (enrolledSchedules.indexOf(scheduleSysId) == -1) {
                var courseId = grSchedules.getValue('course');
                var instructorId = grSchedules.getValue('instructor');
                var trainingDate = grSchedules.getValue('training_date'); // Use getValue
                availableSchedules.push(scheduleSysId);
                gs.info("Available Schedule ID: " + scheduleSysId);
            }
        }

        gs.info("Available Schedules (before checks): " + availableSchedules.join(",")); // Log before filtering

        // Check if user has enrolled in the course more than 3 times.
        var courseCheck = new GlideRecord("x_1593183_traini_0_training_enrollments");
        courseCheck.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe");
        courseCheck.addQuery("course", courseId); // courseId is now defined within the loop
        courseCheck.query();
        var count = 0;
        while (courseCheck.next()) {
            count++;
            if (count >= 3) {
                gs.info("User has enrolled in this course more than 3 times.");
                continue;
            }
        }

        // Check if the user is the instructor.
        if (grSchedules.instructor == userId) {
            gs.info("User is the instructor for this schedule.");
            return false;
        }

        // Check if the training date is in the past (more than 1 day ago).
        var date = new GlideDateTime(trainingDate);
        var today = new GlideDateTime();
        today.addDaysUTC(1); // Add one day to today.
        if (today.compareTo(date) >= 0) {
            gs.info("Training date is in the past.");
            return false;
        }

        gs.info("Available Schedules (after checks): " + availableSchedules.join(",")); // Log after filtering

        if (availableSchedules.length === 0) {
            gs.info("No available schedules found.");
            return false; // Return false if no schedules are available
        }

        return "sys_idIN" + availableSchedules.join(",");
    },

    type: 'TrainingUtils'
};
